def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        background = max(set(row), key=row.count)
        marks = [i for i, value in enumerate(row) if value != background]
        for a, b in zip(marks, marks[1:]):
            if b - a == 2 and row[a] == row[b]:
                row[a + 1] = 2
    return out
